import {test} from 'node:test';import assert from 'node:assert/strict';
import {createApp} from './server.mjs';
test('HTTP contract',async()=>{const app=createApp();await new Promise(r=>app.listen(0,'127.0.0.1',r));try{const response=await fetch('http://127.0.0.1:'+app.address().port,{method:'POST',headers:{Connection:'close'},body:JSON.stringify({"total":10,"reserved":3})});assert.equal(response.status,200);assert.deepEqual(await response.json(),{value:7});}finally{await new Promise(r=>app.close(r));}});

